/**
 * Next.js Metadata for a page: title, description, robots, canonical,
 * reciprocal hreflang, Open Graph and Twitter. Mirrors the tags the site has
 * always shipped, so nothing changes for search engines.
 */
import type { Metadata } from 'next';
import { site, SITE_URL } from './site.mjs';
import { absolute } from './seo';
import { ogLocale, type Lang } from './i18n';
import type { PageDef } from './pages';

const OG_IMAGE = '/images/og-default.png';

/** Favicon, touch icon and manifest, shared by every page (generated by `npm run icons`). */
export const iconMetadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  // favicon.ico first with an explicit 32x32 size, so browsers that
  // understand SVG icons still prefer favicon.svg and older ones fall back.
  icons: {
    icon: [
      { url: '/favicon.ico', sizes: '32x32' },
      { url: '/favicon.svg', type: 'image/svg+xml' },
    ],
    apple: '/icons/apple-touch-icon.png',
  },
  manifest: '/site.webmanifest',
};

export function pageMetadata(page: PageDef): Metadata {
  const { lang, title, description, path, alternates, noindex } = page;
  const canonical = absolute(path);
  const ogImageUrl = absolute(OG_IMAGE);

  return {
    title: { absolute: title },
    description,
    // `follow` is kept on noindex pages so link equity still reaches the hub.
    robots: noindex
      ? { index: false, follow: true }
      : { index: true, follow: true, 'max-image-preview': 'large' },
    alternates: {
      canonical,
      // Reciprocal hreflang. Every page in the group advertises the same set.
      languages: Object.fromEntries(alternates.map((a) => [a.hreflang, a.href])),
    },
    openGraph: {
      type: 'website',
      siteName: site.brand,
      locale: ogLocale[lang],
      alternateLocale: alternates
        .filter((a) => a.hreflang !== 'x-default' && a.hreflang !== lang)
        .map((a) => ogLocale[a.hreflang as Lang]),
      title,
      description,
      url: canonical,
      images: [
        {
          url: ogImageUrl,
          type: 'image/png',
          width: 1200,
          height: 630,
          alt: `${site.brand} — ${description.slice(0, 80)}`,
        },
      ],
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      images: [ogImageUrl],
    },
  };
}
